-- Phase 37 coordinates existing WMS/dispatch/tracking records. These are
-- append-only coordination evidence and do not replace owning-domain state.
CREATE OR REPLACE FUNCTION public.yard37_read(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_company_member(c) AND public.has_any_role(c,ARRAY['admin','warehouse_operator','warehouse_manager','yard_controller','gate_controller','security_officer','dock_coordinator','dispatcher','fleet_controller','driver','technician','compliance_manager','customer_care','executive','viewer']::public.app_role[]) $$;
CREATE OR REPLACE FUNCTION public.yard37_write(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.yard37_read(c) AND public.has_any_role(c,ARRAY['admin','warehouse_operator','warehouse_manager','yard_controller','gate_controller','security_officer','dock_coordinator','dispatcher','fleet_controller']::public.app_role[]) $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['yard_sites','yard_zones','yard_gates','yard_gate_lanes','yard_parking_bays','yard_docks','yard_appointments','yard_gate_visits','yard_visitors','yard_vehicle_states','yard_trailer_states','yard_movements','yard_queue_entries','yard_dock_allocations','yard_loading_sessions','yard_loading_progress','yard_unloading_sessions','yard_unloading_progress','yard_weighbridge_records','yard_seal_records','yard_security_inspections','yard_exceptions','yard_driver_instructions','yard_handover_reports','yard_audit_logs'] LOOP EXECUTE format('CREATE TABLE IF NOT EXISTS public.%I(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,payload jsonb NOT NULL DEFAULT ''{}'',created_at timestamptz NOT NULL DEFAULT now())',t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon',t); EXECUTE format('GRANT SELECT,INSERT ON public.%I TO authenticated',t); EXECUTE format('CREATE POLICY %I_read ON public.%I FOR SELECT TO authenticated USING(public.yard37_read(company_id))',t,t); EXECUTE format('CREATE POLICY %I_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(public.yard37_write(company_id))',t,t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.yard37_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Yard evidence is append-only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['yard_gate_visits','yard_movements','yard_queue_entries','yard_dock_allocations','yard_loading_progress','yard_unloading_progress','yard_weighbridge_records','yard_seal_records','yard_security_inspections','yard_audit_logs'] LOOP EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.yard37_append_only()',t,t); END LOOP; END $$;
CREATE POLICY yard_customer_safe_progress ON public.yard_loading_progress FOR SELECT TO authenticated USING(public.is_company_member(company_id) AND payload ? 'customer_safe' AND (payload->>'customer_safe')::boolean = true);
